import threading
import uuid


class AccountError(Exception):
    """Base class for account related errors."""
    pass


class AccountAlreadyExistsError(AccountError):
    """Raised when attempting to create an account that already exists."""
    pass


class AccountNotFoundError(AccountError):
    """Raised when an account cannot be found."""
    pass


class InvalidAccountDataError(AccountError):
    """Raised when provided account data is invalid."""
    pass


class AccountClosedError(AccountError):
    """Raised when operations are attempted on a closed account."""
    pass


class Account:
    __slots__ = ("account_id", "user_id", "balance", "closed")

    def __init__(self, user_id: str, initial_balance: float):
        self.account_id = str(uuid.uuid4())
        self.user_id = user_id
        self.balance = initial_balance
        self.closed = False


class AccountManager:
    """
    Handles account creation, updates, retrieval, and closure.
    """

    def __init__(self):
        # user_id -> Account
        self._accounts = {}
        self._lock = threading.RLock()

    def _validate_account_data(self, account_data: dict, for_update: bool = False):
        if not isinstance(account_data, dict):
            raise InvalidAccountDataError("Account data must be a dictionary.")
        if not for_update:
            # Creation requires an initial balance
            if "initial_balance" not in account_data:
                raise InvalidAccountDataError("Missing 'initial_balance' in account data.")
        else:
            # Update may contain 'balance' to set a new balance
            if "balance" not in account_data:
                raise InvalidAccountDataError("Missing 'balance' in account data for update.")

        # Validate numeric value
        key = "initial_balance" if not for_update else "balance"
        value = account_data[key]
        if not isinstance(value, (int, float)):
            raise InvalidAccountDataError(f"'{key}' must be a numeric type.")
        if value < 0:
            raise InvalidAccountDataError(f"'{key}' cannot be negative.")

    def create_account(self, user_id: str, account_data: dict):
        """
        Creates a new account for a given user.
        Returns a tuple (account_id, account_balance).
        """
        if not isinstance(user_id, str) or not user_id:
            raise InvalidAccountDataError("User ID must be a non‑empty string.")
        self._validate_account_data(account_data, for_update=False)

        with self._lock:
            if user_id in self._accounts:
                raise AccountAlreadyExistsError(f"Account for user '{user_id}' already exists.")
            initial_balance = float(account_data["initial_balance"])
            account = Account(user_id, initial_balance)
            self._accounts[user_id] = account
            return account.account_id, account.balance

    def update_account(self, user_id: str, account_data: dict):
        """
        Updates an existing account's balance.
        Returns a tuple (account_id, new_balance).
        """
        if not isinstance(user_id, str) or not user_id:
            raise InvalidAccountDataError("User ID must be a non‑empty string.")
        self._validate_account_data(account_data, for_update=True)

        with self._lock:
            if user_id not in self._accounts:
                raise AccountNotFoundError(f"No account found for user '{user_id}'.")
            account = self._accounts[user_id]
            if account.closed:
                raise AccountClosedError(f"Account '{account.account_id}' is closed.")
            new_balance = float(account_data["balance"])
            account.balance = new_balance
            return account.account_id, account.balance

    def get_account(self, user_id: str):
        """
        Retrieves account information.
        Returns a tuple (account_id, account_balance).
        """
        if not isinstance(user_id, str) or not user_id:
            raise InvalidAccountDataError("User ID must be a non‑empty string.")

        with self._lock:
            if user_id not in self._accounts:
                raise AccountNotFoundError(f"No account found for user '{user_id}'.")
            account = self._accounts[user_id]
            if account.closed:
                raise AccountClosedError(f"Account '{account.account_id}' is closed.")
            return account.account_id, account.balance

    def close_account(self, user_id: str):
        """
        Closes an existing account.
        Returns the closed account's ID.
        """
        if not isinstance(user_id, str) or not user_id:
            raise InvalidAccountDataError("User ID must be a non‑empty string.")

        with self._lock:
            if user_id not in self._accounts:
                raise AccountNotFoundError(f"No account found for user '{user_id}'.")
            account = self._accounts[user_id]
            account.closed = True
            return account.account_id


# Example usage (can be removed or adapted for unit tests)
if __name__ == "__main__":
    manager = AccountManager()

    # Create an account
    try:
        acct_id, balance = manager.create_account("user123", {"initial_balance": 100.0})
        print(f"Created account {acct_id} with balance {balance}")
    except AccountError as e:
        print(f"Error: {e}")

    # Retrieve the account
    try:
        acct_id, balance = manager.get_account("user123")
        print(f"Retrieved account {acct_id} with balance {balance}")
    except AccountError as e:
        print(f"Error: {e}")

    # Update the account
    try:
        acct_id, new_balance = manager.update_account("user123", {"balance": 250.0})
        print(f"Updated account {acct_id} to new balance {new_balance}")
    except AccountError as e:
        print(f"Error: {e}")

    # Close the account
    try:
        closed_id = manager.close_account("user123")
        print(f"Closed account {closed_id}")
    except AccountError as e:
        print(f"Error: {e}")

    # Attempt to retrieve a closed account
    try:
        manager.get_account("user123")
    except AccountError as e:
        print(f"Error after closure: {e}")

