import uuid
import hashlib
import secrets
import time
from datetime import datetime, timedelta
from typing import Dict, Optional, Any


class AuthenticationError(Exception):
    pass


class AccountLockedError(AuthenticationError):
    pass


class InvalidCredentialsError(AuthenticationError):
    pass


class AuthModule:
    _LOCKOUT_THRESHOLD = 3               # failed attempts before lockout
    _LOCKOUT_DURATION = timedelta(minutes=5)  # lockout period
    _TOKEN_EXPIRY = timedelta(hours=1)   # token validity

    def __init__(self):
        self._users: Dict[str, Dict[str, Any]] = {}      # key: username
        self._tokens: Dict[str, Dict[str, Any]] = {}     # key: token

    # ----------------------- Helper methods -----------------------

    @staticmethod
    def _hash_password(password: str, salt: str) -> str:
        return hashlib.sha256((salt + password).encode('utf-8')).hexdigest()

    @staticmethod
    def _validate_str(value: str, name: str):
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{name} must be a non‑empty string")

    def _get_user(self, username: str) -> Optional[Dict[str, Any]]:
        return self._users.get(username)

    def _is_locked(self, user: Dict[str, Any]) -> bool:
        lockout_until = user.get('lockout_until')
        if lockout_until and datetime.utcnow() < lockout_until:
            return True
        return False

    def _reset_failed_attempts(self, user: Dict[str, Any]):
        user['failed_attempts'] = 0
        user['lockout_until'] = None

    # ----------------------- Public API -----------------------

    def register(self, username: str, password: str, **extra_data) -> str:
        """
        Register a new user.
        Returns the generated user ID.
        """
        self._validate_str(username, "username")
        self._validate_str(password, "password")

        if username in self._users:
            raise AuthenticationError("Username already exists")

        user_id = str(uuid.uuid4())
        salt = secrets.token_hex(16)
        password_hash = self._hash_password(password, salt)

        self._users[username] = {
            'id': user_id,
            'salt': salt,
            'password_hash': password_hash,
            'failed_attempts': 0,
            'lockout_until': None,
            'extra': extra_data,
        }
        return user_id

    def login(self, username: str, password: str) -> str:
        """
        Authenticate a user and issue an access token.
        Returns the access token.
        """
        self._validate_str(username, "username")
        self._validate_str(password, "password")

        user = self._get_user(username)
        if not user:
            raise InvalidCredentialsError("Invalid credentials")

        if self._is_locked(user):
            raise AccountLockedError("Account is locked. Try later.")

        # Verify password
        expected_hash = self._hash_password(password, user['salt'])
        if expected_hash != user['password_hash']:
            user['failed_attempts'] += 1
            if user['failed_attempts'] >= self._LOCKOUT_THRESHOLD:
                user['lockout_until'] = datetime.utcnow() + self._LOCKOUT_DURATION
                raise AccountLockedError("Account locked due to multiple failed attempts")
            raise InvalidCredentialsError("Invalid credentials")

        # Successful login
        self._reset_failed_attempts(user)

        token = secrets.token_urlsafe(32)
        expiry = datetime.utcnow() + self._TOKEN_EXPIRY
        self._tokens[token] = {
            'user_id': user['id'],
            'expires_at': expiry,
        }
        return token

    def verify_token(self, token: str) -> Optional[str]:
        """
        Verify an access token.
        Returns the associated user ID if valid, otherwise None.
        """
        if not isinstance(token, str) or not token:
            return None
        data = self._tokens.get(token)
        if not data:
            return None
        if datetime.utcnow() > data['expires_at']:
            del self._tokens[token]
            return None
        return data['user_id']

    def reset_password(self, username: str, new_password: str) -> None:
        """
        Reset a user's password. Clears lockout state.
        """
        self._validate_str(username, "username")
        self._validate_str(new_password, "new_password")

        user = self._get_user(username)
        if not user:
            raise AuthenticationError("User not found")

        new_salt = secrets.token_hex(16)
        new_hash = self._hash_password(new_password, new_salt)
        user['salt'] = new_salt
        user['password_hash'] = new_hash
        self._reset_failed_attempts(user)

    # Optional: cleanup expired tokens (could be called periodically)
    def cleanup_expired_tokens(self):
        now = datetime.utcnow()
        expired = [t for t, v in self._tokens.items() if v['expires_at'] < now]
        for t in expired:
            del self._tokens[t]
