import uuid
from typing import Dict, Tuple

# In-memory store for accounts: {account_id: balance}
_accounts: Dict[str, float] = {
    "A001": 5000.0,
    "A002": 3000.0,
    "A003": 0.0,
}

# Transfer limits per type (maximum amount allowed per transaction)
_transfer_limits: Dict[str, float] = {
    "instant": 2000.0,
    "scheduled": 5000.0,
    "internal": 10000.0,
}


class TransactionError(Exception):
    """Base class for transaction related errors."""
    pass


class InsufficientFundsError(TransactionError):
    pass


class InvalidRecipientError(TransactionError):
    pass


class TransferLimitExceededError(TransactionError):
    pass


def validate_inputs(sender_id: str, recipient_id: str, amount: float, transfer_type: str) -> None:
    if not isinstance(sender_id, str) or not sender_id:
        raise ValueError("Sender ID must be a non‑empty string.")
    if not isinstance(recipient_id, str) or not recipient_id:
        raise ValueError("Recipient ID must be a non‑empty string.")
    if sender_id == recipient_id:
        raise ValueError("Sender and recipient IDs must be different.")
    if not isinstance(amount, (int, float)):
        raise ValueError("Transfer amount must be a number.")
    if amount <= 0:
        raise ValueError("Transfer amount must be greater than zero.")
    if transfer_type not in _transfer_limits:
        raise ValueError(f"Unsupported transfer type '{transfer_type}'. Supported types: {list(_transfer_limits)}")


def get_balance(account_id: str) -> float:
    """Return the balance of the given account, raising KeyError if missing."""
    return _accounts[account_id]


def set_balance(account_id: str, new_balance: float) -> None:
    """Set the balance for an account."""
    _accounts[account_id] = new_balance


def process_transfer(sender_id: str, recipient_id: str, amount: float, transfer_type: str) -> Dict[str, str]:
    """
    Process a money transfer between two accounts.

    Returns:
        {
            "transaction_id": "<uuid>",
            "transfer_status": "success" | "failed: <reason>"
        }
    """
    try:
        validate_inputs(sender_id, recipient_id, amount, transfer_type)

        # Verify both accounts exist
        if sender_id not in _accounts:
            raise InvalidRecipientError(f"Sender account '{sender_id}' does not exist.")
        if recipient_id not in _accounts:
            raise InvalidRecipientError(f"Recipient account '{recipient_id}' does not exist.")

        # Check transfer limit
        limit = _transfer_limits[transfer_type]
        if amount > limit:
            raise TransferLimitExceededError(f"Amount {amount} exceeds limit of {limit} for type '{transfer_type}'.")

        # Check sufficient funds
        if get_balance(sender_id) < amount:
            raise InsufficientFundsError("Insufficient funds in sender account.")

        # Perform transfer
        sender_new_balance = get_balance(sender_id) - amount
        recipient_new_balance = get_balance(recipient_id) + amount
        set_balance(sender_id, sender_new_balance)
        set_balance(recipient_id, recipient_new_balance)

        transaction_id = str(uuid.uuid4())
        status = "success"
    except (ValueError, TransactionError) as e:
        transaction_id = str(uuid.uuid4())
        status = f"failed: {str(e)}"

    return {
        "transaction_id": transaction_id,
        "transfer_status": status,
